-- The request budget (host.ts `rate` rows). One atomic upsert per request decides the
-- count, because a select-then-update lets two concurrent requests both read the same
-- value and both write value+1 — exceeding the ceiling by exactly the traffic it exists for.
create table if not exists dsx_rate_counter (
  bucket text not null,
  window_start timestamptz not null,
  expires_at timestamptz not null,
  count integer not null default 0,
  primary key (bucket, window_start)
);
