alter table dsx_rate_counter enable row level security;
revoke all on dsx_rate_counter from anon, authenticated;
grant select, insert, update, delete on dsx_rate_counter to service_role;
drop policy if exists dsx_rate_counter_service on dsx_rate_counter;
create policy dsx_rate_counter_service on dsx_rate_counter for all to service_role using (true) with check (true);

-- The durable subscription feed (realtime.ts). A CURSOR over a table rather than a
-- pub/sub channel: NOTIFY delivers only to whoever is connected at that instant, so every
-- backgrounded phone silently misses events, and neither end can tell. `owner_id` being
-- nullable IS the authorization model — a row with an owner reaches that subject only.
create table if not exists dsx_event (
  seq bigint generated by default as identity primary key,
  channel text not null,
  owner_id uuid,
  payload jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);
create index if not exists dsx_event_channel_seq_idx on dsx_event (channel, seq);
create index if not exists dsx_event_created_idx on dsx_event (created_at);
alter table dsx_event enable row level security;
revoke all on dsx_event from anon, authenticated;
grant select, insert, delete on dsx_event to service_role;
drop policy if exists dsx_event_service on dsx_event;
create policy dsx_event_service on dsx_event for all to service_role using (true) with check (true);
